import { describe, expect, it } from 'vitest';
import type { CameraRaycaster } from './CameraCollision';
import { cameraPoseDistance, createCameraPose } from './CameraPose';
import { CameraTransition } from './CameraTransition';
import type { EasingName } from './Easing';
import { EASINGS, resolveEasing } from './Easing';
import { SmoothCameraRig } from './SmoothCameraRig';
import {
  clampDeltaSeconds,
  createScalarSpringState,
  createVec3SpringState,
  damp,
  dampAngle,
  dampFactor,
  smoothDamp,
  smoothDampVec3,
  wrapAngle,
} from './Smoothing';

const FRAME = 1 / 60;

describe('easing curves', () => {
  it('start at zero and end at one', () => {
    for (const name of Object.keys(EASINGS) as EasingName[]) {
      expect(EASINGS[name](0)).toBeCloseTo(0, 10);
      expect(EASINGS[name](1)).toBeCloseTo(1, 10);
    }
  });

  it('resolve named, custom and unknown easings', () => {
    const custom = (t: number) => t;
    expect(resolveEasing('linear')).toBe(EASINGS.linear);
    expect(resolveEasing(custom)).toBe(custom);
    expect(resolveEasing()).toBe(EASINGS.easeInOutCubic);
    expect(resolveEasing('nope' as EasingName)).toBe(EASINGS.easeInOutCubic);
  });
});

describe('exponential damping', () => {
  it('ignores non-positive and invalid deltas', () => {
    expect(dampFactor(0.2, 0)).toBe(0);
    expect(dampFactor(0.2, Number.NaN)).toBe(0);
    expect(clampDeltaSeconds(-1)).toBe(0);
    expect(clampDeltaSeconds(0.5, 0.1)).toBe(0.1);
    expect(clampDeltaSeconds(0.05, 0.1)).toBe(0.05);
  });

  it('snaps instantly when the smoothing time is zero', () => {
    expect(dampFactor(0, FRAME)).toBe(1);
    expect(damp(3, 9, 0, FRAME)).toBe(9);
  });

  it('is frame rate independent', () => {
    let stepped = 0;
    for (let i = 0; i < 10; i += 1) stepped = damp(stepped, 10, 0.25, 0.016);
    expect(stepped).toBeCloseTo(damp(0, 10, 0.25, 0.16), 9);
  });

  it('takes the short way around when damping angles', () => {
    expect(wrapAngle(Math.PI * 1.5)).toBeCloseTo(-Math.PI / 2, 10);
    expect(dampAngle(3, -3, 0.1, 0.1)).toBeGreaterThan(3);
  });
});

describe('smoothDamp', () => {
  it('converges without overshooting', () => {
    const state = createScalarSpringState();
    let value = 0;
    let peak = 0;
    for (let i = 0; i < 240; i += 1) {
      value = smoothDamp(value, 10, state, 0.3, FRAME);
      peak = Math.max(peak, value);
    }
    expect(peak).toBeLessThanOrEqual(10 + 1e-9);
    expect(value).toBeCloseTo(10, 4);
  });

  it('keeps the current value and velocity for invalid deltas', () => {
    const state = createScalarSpringState(5);
    expect(smoothDamp(2, 10, state, 0.3, 0)).toBe(2);
    expect(state.velocity).toBe(5);
  });

  it('limits how far the value may travel in one step', () => {
    const limited = smoothDamp(0, 100, createScalarSpringState(), 0.5, 0.1, 2);
    const free = smoothDamp(0, 100, createScalarSpringState(), 0.5, 0.1);
    expect(limited).toBeLessThan(free);
  });

  it('moves a vector onto the target and settles', () => {
    const state = createVec3SpringState();
    let value = { x: 0, y: 0, z: 0 };
    for (let i = 0; i < 300; i += 1) {
      value = smoothDampVec3(value, { x: 4, y: -2, z: 7 }, state, 0.25, FRAME);
    }
    expect(value.x).toBeCloseTo(4, 4);
    expect(value.y).toBeCloseTo(-2, 4);
    expect(value.z).toBeCloseTo(7, 4);
    expect(Math.hypot(state.velocity.x, state.velocity.y, state.velocity.z)).toBeLessThan(0.01);
  });
});

const blockingRaycaster: CameraRaycaster = { cast: () => ({ distance: 2 }) };
const poseHelpers = { cameraPoseDistance, createCameraPose, CameraTransition, SmoothCameraRig, blockingRaycaster };
void poseHelpers;
EOF
